message.content:
{
  "candidate_edge_types": [
    {
      "name": "INVESTIGATES_ERROR_CAUSE",
      "definition": "After a verification run produces an error, a subsequent agent action searches or inspects the source to locate the origin of the failure before attempting any fix.",
      "source_description": "An observed execution error or failure produced by a prior verification step.",
      "target_description": "An agent action that searches the codebase or configuration to locate the source of the reported error."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action modifies source or configuration and rebuilds/reinstalls artifacts in order to resolve a previously diagnosed failure.",
      "source_description": "A previously diagnosed failure cause or observed execution failure.",
      "target_description": "An agent action that edits files and rebuilds/deploys them with the intent of resolving the failure."
    },
    {
      "name": "VERIFIES_REPAIR_SUCCESS",
      "definition": "After a repair action, the agent re-executes the previously failing operation to determine whether the repair resolved the failure.",
      "source_description": "A repair action that modified or rebuilt an artifact to address an earlier failure.",
      "target_description": "A subsequent re-execution of the previously failing command or check used to confirm the repair."
    },
    {
      "name": "DECLARES_COMPLETION_BASED_ON_VERIFICATION",
      "definition": "The agent marks the task as complete after a final verification run confirms that all required conditions are satisfied.",
      "source_description": "A successful verification or test result confirming the required behavior.",
      "target_description": "A task-completion action or decision that concludes the execution."
    }
  ]
}

